  `imageCredit` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `readingTime` int NOT NULL DEFAULT '3',
  `featuredType` enum('NONE','HERO','SECONDARY','EDITORS_PICK') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'NONE',
  `status` enum('DRAFT','PENDING_REVIEW','APPROVED','SCHEDULED','PUBLISHED','ARCHIVED') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'DRAFT',
  `publishedAt` datetime(3) DEFAULT NULL,
