INSERT INTO `category` VALUES ('cat_amirs-corner','Amir\'s Corner','amirs-corner','Direct addresses, guidance, and key messages from Amir Sahib Ahmadiyya Muslim Jamaat Nigeria.',NULL,'#15803d',10,'2026-11-14 11:34:34.878','2026-11-14 11:34:34.877'),('cat_convention-lectures','Convention Lectures','convention-lectures','Transcripts, summaries, and recordings of scholarly lectures delivered during Jalsa sessions.',NULL,'#4338ca',10,'2026-11-14 11:34:34.886','2026-11-14 11:34:34.884'),('cat_news-reports','News & Reports','news-reports','Comprehensive news coverage, reports, and real-time updates from Jalsa Salana events.',NULL,'#0f766e',10,'2026-11-14 11:34:34.866','2026-11-14 11:34:34.864'),('cat_poems-reflections','Poems & Reflections','poems-reflections','Heartfelt poems, personal memories, and spiritual reflections penned by attendees and volunteers.',NULL,'#a21caf',10,'2026-11-14 11:34:34.897','2026-11-14 11:34:34.896'),('cmw7zfjvv000ew4d9leosc0l9','Faith & Spirituality','faith-spirituality','Theological treatises, commentary on the Holy Quran, and reflections on spiritual purification.',NULL,'#064e3b',1,'2026-11-08 15:23:40.267','2026-11-08 15:23:40.267'),('cmw7zfjw3000fw4d9uon1xbr7','Social Justice & Peace','social-justice-peace','Islamic prescriptions for equitable governance, poverty alleviation, and peaceful coexistence.',NULL,'#b45309',2,'2026-11-08 15:23:40.276','2026-11-08 15:23:40.276'),('cmw7zfjwb000gw4d90j1b55xn','Khilafat & Guidance','khilafat-guidance','Divine leadership, guidance of the Khalifatul Masih, and the unity of the global community.',NULL,'#1d4ed8',3,'2026-11-08 15:23:40.283','2026-11-08 15:23:40.283'),('cmw7zfjwi000hw4d922105uiv','Tarbiyya & Youth','tarbiyya-youth','Moral training, character development, and empowering the next generation of leadership.',NULL,'#047857',4,'2026-11-08 15:23:40.291','2026-11-08 15:23:40.291'),('cmw7zfjwr000iw4d9rgrqiofo','Press Conferences','press-conference','Official communiques, media briefings, and public declarations issued at Jalsa Salana.',NULL,'#6b21a8',5,'2026-11-08 15:23:40.299','2026-11-08 15:23:40.299'),('cmw7zfjwy000jw4d9awaore7p','History & Heritage','history-heritage','Over a century of Ahmadiyya history in Nigeria and documentary records of past Jalsa editions.',NULL,'#991b1b',6,'2026-11-08 15:23:40.307','2026-11-08 15:23:40.307'),('cmw7zfjx6000kw4d9a6cl1wvh','Guest Impressions','guest-impressions','Reflections and testimonies from national dignitaries, traditional rulers, and interfaith guests.',NULL,'#0e7490',7,'2026-11-08 15:23:40.314','2026-11-08 15:23:40.314');
