INSERT INTO `gallery` VALUES ('cmw7zfk2s001bw4d9jkqgx5l8','70th Platinum Jubilee Highlights — Jalsa Salana Nigeria','70th-platinum-jubilee-highlights','Stunning visual moments capturing the 70th Annual Convention at Jamia Ahmadiyya Ilaro, featuring prayer sessions, scholarly addresses, and international delegates.','/images/jalsa_gallery/jalsa-main-stage-keynote-podium.jpg','Jalsa Media Nigeria Photojournalism Unit','December 20–22, 2024',NULL,'cmw7zfjxw000nw4d9dkgl8oq5','2026-11-08 15:23:40.516','2026-11-14 16:25:38.835');
