INSERT INTO `media` VALUES ('cmwgmad6k0000lbf5dwq0nuye','Keynote Address & Main Stage Dais','Keynote presentation delivered from the floral podium of the 70th Platinum Jubilee.','Official Jalsa Media','/images/jalsa_gallery/jalsa-main-stage-keynote-podium.jpg','image/jpeg',191675,NULL,NULL,NULL,'2026-11-14 16:25:38.876','2026-11-14 16:25:38.876'),('cmwgmad770003lbf54pmcmugl','Night Tahajjud Prayer in Grand Marquee','Tahajjud and Fajr prayers illuminated under the grand convention marquee.','Official Jalsa Media','/images/jalsa_gallery/jalsa-night-marquee-tahajjud.jpg','image/jpeg',192931,NULL,NULL,NULL,'2026-11-14 16:25:38.899','2026-11-14 16:25:38.899'),('cmwgmad7p0006lbf53eboq24r','Executive State Reception with Governor','His Excellency Prince Dapo Abiodun, Governor of Ogun State, received by National Amir.','Official Jalsa Media','/images/jalsa_gallery/jalsa-governor-abiodun-amir-handshake.jpg','image/jpeg',158777,NULL,NULL,NULL,'2026-11-14 16:25:38.917','2026-11-14 16:25:38.917'),('cmwgmad870009lbf5d47autkr','Discipline & Volunteer Security Corps','Majlis Khuddamul Ahmadiyya discipline and security corps in uniform.','Official Jalsa Media','/images/jalsa_gallery/jalsa-khuddam-security-discipline.jpg','image/jpeg',189916,NULL,NULL,NULL,'2026-11-14 16:25:38.935','2026-11-14 16:25:38.935'),('cmwgmad8n000clbf5q4y87ixb','Ride to Jalsa — Cycling Caravan Arrival','Ahmadiyya Cycling Association riders arriving in team kits on convention grounds.','Official Jalsa Media','/images/jalsa_gallery/jalsa-cycling-association-arrival.jpg','image/jpeg',145463,NULL,NULL,NULL,'2026-11-14 16:25:38.951','2026-11-14 16:25:38.951'),('cmwgmad93000flbf58h0cbtef','Royal Obas & Traditional Custodians','Traditional Royal Obas in beaded crowns seated in the VIP gallery.','Official Jalsa Media','/images/jalsa_gallery/jalsa-traditional-rulers-obas.jpg','image/jpeg',190877,NULL,NULL,NULL,'2026-11-14 16:25:38.967','2026-11-14 16:25:38.967'),('cmwgmad9k000ilbf5t2v19xtv','Volunteers and Attendees in Salat','Duty volunteers and delegates joined in prayer rows.','Official Jalsa Media','/images/jalsa_gallery/jalsa-prayer-volunteers-salat.jpg','image/jpeg',128359,NULL,NULL,NULL,'2026-11-14 16:25:38.984','2026-11-14 16:25:38.984'),('cmwgmada0000llbf5117rj0or','Gathering of Faithful Hearts','Delegates and attendees listening attentively under the convention canopy.','Official Jalsa Media','/images/jalsa_gallery/jalsa-crowd-marquee-gathering.jpg','image/jpeg',169097,NULL,NULL,NULL,'2026-11-14 16:25:39.000','2026-11-14 16:25:39.000'),('cmwgmadaf000olbf5hdqoj8uz','Interfaith Goodwill Interview','Christian Archbishop sharing message of peace during MTA interview at Jalsa.','Official Jalsa Media','/images/jalsa_gallery/jalsa-interfaith-archbishop-interview.jpg','image/jpeg',89756,NULL,NULL,NULL,'2026-11-14 16:25:39.015','2026-11-14 16:25:39.015'),('cmwgmadaw000rlbf5ii52uib0','Royal Oba on Dais with Amir','Royal Oba with royal staff of office and coral regalia received on stage.','Official Jalsa Media','/images/jalsa_gallery/jalsa-royal-oba-coronation-amir.jpg','image/jpeg',65439,NULL,NULL,NULL,'2026-11-14 16:25:39.033','2026-11-14 16:25:39.033'),('cmwgmadbb000ulbf57n1rtti0','Silent Supplication & Dua','Deep collective contemplation and tearful prayer with hands raised.','Official Jalsa Media','/images/jalsa_gallery/jalsa-silent-prayer-dua.jpg','image/jpeg',138158,NULL,NULL,NULL,'2026-11-14 16:25:39.047','2026-11-14 16:25:39.047'),('cmwgmadbq000xlbf5q87nom8m','Outdoor Prayer on Convention Lawn','Congregational prayer rows spread out on the green lawn.','Official Jalsa Media','/images/jalsa_gallery/jalsa-outdoor-prayer-lawn.jpg','image/jpeg',212056,NULL,NULL,NULL,'2026-11-14 16:25:39.062','2026-11-14 16:25:39.062');
