DROP TABLE IF EXISTS `zone_traffic`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `zone_traffic` (
  `id` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `zoneKey` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `type` enum('DINING','SANITARY','PRAYER','PARKING','ENTRANCE','CLINIC') COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` enum('GREEN','ORANGE','RED') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'GREEN',
  `currentOccupancy` int NOT NULL DEFAULT '0',
  `maxCapacity` int NOT NULL DEFAULT '1000',
  `alternateZoneId` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `alternateNote` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `mapCoordinates` json DEFAULT NULL,
  `lastUpdatedBy` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updatedAt` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `zone_traffic_zoneKey_key` (`zoneKey`),
  KEY `zone_traffic_type_idx` (`type`),
  KEY `zone_traffic_status_idx` (`status`),
  KEY `zone_traffic_alternateZoneId_fkey` (`alternateZoneId`),
  CONSTRAINT `zone_traffic_alternateZoneId_fkey` FOREIGN KEY (`alternateZoneId`) REFERENCES `zone_traffic` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

