INSERT INTO `zone_traffic` VALUES ('cmwgwf9b50000128vwbbfuvu7','aux-dining-male','Auxiliary Dining Marquee B (Men)','DINING','GREEN',420,1500,NULL,'Directly behind Administrative Block; spacious seating available.','{\"x\": 38, \"y\": 48, \"label\": \"Aux Dining B\"}','Logistics Command','2026-11-14 21:09:23.297','2026-11-16 12:47:40.032'),('cmwgwf9bq0002128vbihq97zn','main-dining-male','Main Dining Hall (Men)','DINING','RED',2480,2500,'cmwgwf9b50000128vwbbfuvu7','Capacity reached. Delegates redirected to Auxiliary Dining Marquee B (3 min walk).','{\"x\": 32, \"y\": 42, \"label\": \"Main Dining (Men)\"}','Food Committee Lead','2026-11-14 21:09:23.318','2026-11-16 12:47:40.016'),('cmwgwf9c60003128vdkb6yw9v','lajna-dining-annex','Lajna Annex Dining Pavilion','DINING','GREEN',350,1200,NULL,'Situated adjacent to Lajna Guest Lodge.','{\"x\": 74, \"y\": 38, \"label\": \"Lajna Dining Annex\"}','Lajna Welfare Team','2026-11-14 21:09:23.335','2026-11-16 12:47:40.047'),('cmwgwf9cm0005128vp0vz4n07','lajna-dining-main','Lajna Main Dining Complex','DINING','RED',2180,2200,'cmwgwf9c60003128vdkb6yw9v','Fast moving queues; Annex Dining available for nursing mothers and elders.','{\"x\": 68, \"y\": 32, \"label\": \"Lajna Main Dining\"}','Lajna Food Sec.','2026-11-14 21:09:23.350','2026-11-16 12:47:40.039'),('cmwgwf9cy0006128vjd4oluq3','gate-west-2','West Registration Hub & Gate 2','ENTRANCE','GREEN',1800,6000,NULL,'8 high-speed biometric scanning lanes active; zero queue delay.','{\"x\": 18, \"y\": 65, \"label\": \"Gate 2 (West)\"}','Security Protocol','2026-11-14 21:09:23.362','2026-11-14 21:09:23.362'),('cmwgwf9d90008128v8uzpyif2','gate-north-1','North Expressway Gate 1','ENTRANCE','RED',4850,5000,'cmwgwf9cy0006128vjd4oluq3','Heavy arrival influx on expressway. Follow marshals to Gate 2 (West Entrance).','{\"x\": 22, \"y\": 15, \"label\": \"Gate 1 (North)\"}','Traffic Marshall','2026-11-14 21:09:23.373','2026-11-14 21:09:23.373'),('cmwgwf9dl0009128vw6iyer0d','sanitary-men-b','Ablution Complex B (Behind Minaret)','SANITARY','GREEN',85,350,NULL,'120 running water taps open with instant access.','{\"x\": 46, \"y\": 28, \"label\": \"Ablution B\"}','Sanitation Corps','2026-11-14 21:09:23.385','2026-11-14 21:09:23.385'),('cmwgwf9du000b128ver1if1wy','sanitary-men-a','Main Ablution Complex A (Front Courtyard)','SANITARY','RED',395,400,'cmwgwf9dl0009128vw6iyer0d','Peak prayer rush. Proceed 50 meters east to Ablution Complex B.','{\"x\": 42, \"y\": 22, \"label\": \"Ablution A (Front)\"}','Sanitation Corps','2026-11-14 21:09:23.394','2026-11-14 21:09:23.394'),('cmwgwf9e6000c128vqc1x5gqg','sanitary-women-a','Lajna Ablution & Sanitary Complex','SANITARY','GREEN',210,500,NULL,'Comfortable capacity with full utility services.','{\"x\": 80, \"y\": 44, \"label\": \"Lajna Sanitary\"}','Lajna Sanitation','2026-11-14 21:09:23.407','2026-11-14 21:09:23.407'),('cmwgwf9ei000d128vf23qgxkg','main-prayer-hall','Main Convention Prayer Marquee (Men)','PRAYER','GREEN',8400,15000,NULL,'Front rows filling; Center and rear aisles open with high-definition audio monitors.','{\"x\": 48, \"y\": 55, \"label\": \"Main Prayer Marquee\"}','Protocol Desk','2026-11-14 21:09:23.418','2026-11-14 21:09:23.418'),('cmwgwf9eu000e128vejc7ehyl','lajna-prayer-pavilion','Lajna Main Prayer Pavilion','PRAYER','GREEN',6900,12000,NULL,'Ample seating in sections C through F with live video stream projection.','{\"x\": 72, \"y\": 62, \"label\": \"Lajna Prayer Pavilion\"}','Lajna Protocol','2026-11-14 21:09:23.430','2026-11-14 21:09:23.430'),('cmwgwf9f7000f128vrabehn31','medical-center','Central Ahmadiyya Medical Clinic','CLINIC','GREEN',18,120,NULL,'Doctors on duty 24/7. First aid, triage, and pharmacy fully stocked.','{\"x\": 55, \"y\": 35, \"label\": \"Medical Clinic\"}','Ahmadiyya Medical Guild','2026-11-14 21:09:23.443','2026-11-14 21:09:23.443'),('cmwgwf9fk000g128vnckubqzb','parking-west','West Convoy & Bus Terminal','PARKING','GREEN',540,1200,NULL,'Sectors 1 to 4 open for interstate buses and chartered vehicles.','{\"x\": 12, \"y\": 78, \"label\": \"West Parking\"}','Traffic Marshals','2026-11-14 21:09:23.456','2026-11-14 21:09:23.456');
